-- Phong Than "Lenh Bai Luyen Cong" (magicscript 61420, 2026-10-03, agent luyencong). Permanent, never consumed
-- (KItemList::ExecuteScript only calls main; this script never removes the item). Generated by
-- scratchpad\luyencong\gen.py - edit the generator, not this file. Doc: docs\features\lenh-bai-luyen-cong-phong-than-20261003.md
-- Right click: 20 leveling spots by level band (1-150), 4 pages of 5. Choosing one = NewWorld to a cell next to the
-- densest monster cluster of that band, then SetFightState(1). Row 1 "Bai hop cap nhat" = band of the current level;
-- "Ve thanh gan nhat" = nearest of 5 cities by WorldSet MapPos, at the VNG Chi Nam Phu arrival points.
-- Spot cells: monsters of spawn_<map>.lua (1014: original VNG Region_S records), cell walkable with its 8 neighbours
-- on the client grid and the server Region_S grid, no trap, >= 3 cells from a monster (scratchpad\luyencong\pick.py).
-- Only usable from field maps / cities (1001-1057, 1065, 1074-1078): never out of events, instances, Thien Lao.
-- Lua 4 / engine: one small statement per record (stack 120 slots), no top-level dofile, menus <= 7 rows.

PTLC_ITEM = 61420

function PTLC_Add(lo, hi, m, x, y, mlo, mhi, nm)
	local s = {}
	s.lo = lo
	s.hi = hi
	s.map = m
	s.x = x
	s.y = y
	s.mlo = mlo
	s.mhi = mhi
	s.nm = nm
	PTLC_N = PTLC_N + 1
	PTLC_S[PTLC_N] = s
end

function PTLC_City(k, m, x, y, nm)
	local c = {}
	c.map = m
	c.x = x
	c.y = y
	c.nm = nm
	PTLC_C[k] = c
end

