function PTLC_No()
end

function PTLC_Say(title, o)
	local n = getn(o)
	local t = { title, n }
	local k = 1
	while k <= n do t[k + 2] = o[k] k = k + 1 end
	call(Say, t)
end

-- map id of the player if the token may be used here, else nil
function PTLC_SrcOk()
	local m = GetWorldPos()
	if not m then return nil end
	if m >= 1001 and m <= 1057 then return m end
	if m == 1065 or (m >= 1074 and m <= 1078) then return m end
	return nil
end

function PTLC_Blocked()
	Say("<color=yellow>L\214nh B\181i Luy\214n C\171ng<color>: kh\171ng d\239ng \174\173\238c \235 b\182n \174\229 n\181y (s\249 ki\214n, ph\227 b\182n, chi\213n tr\173\234ng, Thi\170n Lao). H\183y ra b\182n \174\229 ngo\181i ho\198c v\210 th\181nh tr\173\237c.", 1, "\167\227ng/PTLC_No")
end

function PTLC_LvText(s)
	if s.mlo == s.mhi then return s.mlo .. "" end
	return s.mlo .. "-" .. s.mhi
end

-- index of the spot whose level band holds lv (bands are contiguous from 1)
function PTLC_Best(lv)
	local k = 1
	local i = 1
	while i <= PTLC_N do
		if PTLC_S[i].lo <= lv then k = i end
		i = i + 1
	end
	return k
end

function PTLC_Title(lv)
	return "<color=yellow>L\214nh B\181i Luy\214n C\171ng<color>: c\202p hi\214n t\185i " .. lv .. ". Ch\228n b\183i \174\211 d\222ch chuy\211n t\237i ngay ch\231 c\227 qu\184i (d\202u * = h\238p c\202p). \167\214 t\246 \174i theo s\207 r\234i \174i khi \174\230i b\182n \174\229, d\239ng l\214nh b\181i tri\214u h\229i g\228i l\185i."
end

function PTLC_Main()
	PTLC_Load()
	local lv = GetLevel()
	local s = PTLC_S[PTLC_Best(lv)]
	local o = {}
	o[1] = "B\183i h\238p c\202p nh\202t: " .. s.nm .. " (qu\184i " .. PTLC_LvText(s) .. ")/PTLC_GoBest"
	o[2] = "B\183i c\202p 1-24/PTLC_P1"
	o[3] = "B\183i c\202p 25-49/PTLC_P2"
	o[4] = "B\183i c\202p 50-74/PTLC_P3"
	o[5] = "B\183i c\202p 75-150/PTLC_P4"
	o[6] = "V\210 th\181nh g\199n nh\202t/PTLC_Town"
	o[7] = "\167\227ng/PTLC_No"
	PTLC_Say(PTLC_Title(lv), o)
end

function PTLC_Page(first, last)
	PTLC_Load()
	local lv = GetLevel()
	local b = PTLC_Best(lv)
	local o = {}
	local n = 0
	local i = first
	while i <= last and PTLC_S[i] do
		local s = PTLC_S[i]
		local t = "C\202p " .. s.lo .. "-" .. s.hi .. ": " .. s.nm .. " (qu\184i " .. PTLC_LvText(s) .. ")"
		if i == b then t = t .. " *" end
		n = n + 1
		o[n] = t .. "/PTLC_G" .. i
		i = i + 1
	end
	n = n + 1 o[n] = "Quay l\185i/PTLC_Main"
	n = n + 1 o[n] = "\167\227ng/PTLC_No"
	PTLC_Say(PTLC_Title(lv), o)
end

function PTLC_P1() PTLC_Page(1, 5) end
