function PTLC_P3() PTLC_Page(11, 15) end
function PTLC_P4() PTLC_Page(16, 20) end

function PTLC_Go(k)
	PTLC_Load()
	local s = PTLC_S[k]
	if not s then return end
	if not PTLC_SrcOk() then PTLC_Blocked() return end
	local sw = SubWorldID2Idx(s.map)
	if not sw or sw < 0 then
		Msg2Player("B\182n \174\229 " .. s.nm .. " ch\173a \174\173\238c m\235 tr\170n m\184y ch\241.")
		return
	end
	local r = NewWorld(s.map, s.x, s.y)
	if r == 0 then
		Msg2Player("Kh\171ng d\222ch chuy\211n \174\173\238c t\237i " .. s.nm .. ".")
		return
	end
	SetFightState(1)
	Msg2Player("\167\183 t\237i b\183i luy\214n c\171ng " .. s.nm .. " [" .. floor(s.x / 8) .. "," .. floor(s.y / 16) .. "], qu\184i c\202p " .. PTLC_LvText(s) .. ".")
end

function PTLC_GoBest() PTLC_Load() PTLC_Go(PTLC_Best(GetLevel())) end
