function PTLC_Town()
	PTLC_Load()
	local m = PTLC_SrcOk()
	if not m then PTLC_Blocked() return end
	local c = PTLC_C[PTLC_T[m] or 1]
	local r = NewWorld(c.map, c.x, c.y)
	if r == 0 then
		Msg2Player("Kh\171ng d\222ch chuy\211n \174\173\238c t\237i " .. c.nm .. ".")
		return
	end
	SetFightState(0)
	Msg2Player("\167\183 v\210 " .. c.nm .. ".")
end

